package com.amilingo.platform.module.patent.service;
import com.amilingo.platform.module.patent.dto.PatentWorkflowDTO.*;import com.amilingo.platform.module.patent.entity.*;import com.amilingo.platform.module.patent.repository.*;
import org.junit.jupiter.api.*;import org.mockito.*;import java.time.LocalDate;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.ArgumentMatchers.any;import static org.mockito.Mockito.*;
class PatentWorkflowServiceTest{
 @Mock PatentRepository patentRepo;@Mock PatentDisclosureRepository disclosureRepo;@Mock PatentStatusHistoryRepository historyRepo;@Mock PatentProjectLinkRepository linkRepo;@Mock PatentMaterialCardRepository cardRepo;@Mock PatentInventorRepository inventorRepo;
 AutoCloseable mocks;PatentWorkflowService service;@BeforeEach void setup(){mocks=MockitoAnnotations.openMocks(this);service=new PatentWorkflowService(patentRepo,disclosureRepo,historyRepo,linkRepo,cardRepo,inventorRepo);}@AfterEach void close()throws Exception{mocks.close();}
 @Test void disclosureCanBeSavedInDraft(){when(patentRepo.findById(1L)).thenReturn(Optional.of(patent("DISCLOSURE_DRAFT")));when(disclosureRepo.findByPatentId(1L)).thenReturn(Optional.empty());when(disclosureRepo.save(any())).thenAnswer(i->i.getArgument(0));PatentDisclosure d=service.saveDisclosure(1L,new DisclosureRequest(7L,"背景","缺陷","问题","技术方案","创新","效果","实施","附图","参数","替代",5,List.of()));assertEquals("技术方案",d.getTechnicalSolution());assertEquals("DRAFT",d.getStatus());}
 @Test void invalidStatusTransitionIsRejected(){when(patentRepo.findById(1L)).thenReturn(Optional.of(patent("DISCLOSURE_DRAFT")));StatusChangeRequest r=new StatusChangeRequest(7L,"GRANTED",LocalDate.now(),null,List.of(),null,"G1");assertThrows(IllegalStateException.class,()->service.changeStatus(1L,r));}
 @Test void filingRequiresApplicationNumber(){when(patentRepo.findById(1L)).thenReturn(Optional.of(patent("MATERIAL_PREPARATION")));StatusChangeRequest r=new StatusChangeRequest(7L,"FILED",LocalDate.now(),null,List.of(),null,null);assertThrows(IllegalArgumentException.class,()->service.changeStatus(1L,r));}
 @Test void duplicateProjectLinkIsRejected(){when(patentRepo.findById(1L)).thenReturn(Optional.of(patent("FILED")));when(linkRepo.existsByPatentIdAndResearchProjectIdAndDeliverableIdAndStatus(1L,10L,20L,"ACTIVE")).thenReturn(true);assertThrows(IllegalArgumentException.class,()->service.linkProject(1L,new ProjectLinkRequest(7L,10L,20L,"REPORT",null)));}
 @Test void duplicateInventorOrderIsRejected(){when(patentRepo.findById(1L)).thenReturn(Optional.of(patent("FILED")));when(inventorRepo.existsByPatentIdAndInventorOrder(1L,1)).thenReturn(true);assertThrows(IllegalArgumentException.class,()->service.addInventor(1L,new InventorRequest(7L,8L,"发明人","学校",1,true,"贡献","a@b.com",null)));}
 @Test void approvedDisclosureGeneratesThreeCards(){PatentDisclosure d=PatentDisclosure.builder().id(9L).patentId(1L).status("APPROVED").technicalProblem("问题").technicalSolution("方案").innovations("创新").beneficialEffects("效果").build();when(patentRepo.findById(1L)).thenReturn(Optional.of(patent("MATERIAL_PREPARATION")));when(disclosureRepo.findByPatentId(1L)).thenReturn(Optional.of(d));when(disclosureRepo.findById(9L)).thenReturn(Optional.of(d));when(cardRepo.findFirstByPatentIdOrderByCardNoDesc(1L)).thenReturn(Optional.empty());when(cardRepo.save(any())).thenAnswer(i->i.getArgument(0));List<PatentMaterialCard> cards=service.generateCardsFromDisclosure(1L,new MaterialCardGenerationRequest(7L));assertEquals(3,cards.size());verify(cardRepo,times(3)).save(any());}
 private Patent patent(String status){return Patent.builder().id(1L).userId(7L).name("专利").type("INVENTION").status(status).build();}
}
